 * any property that cannot be serialized (Closures, translators, etc.).
 *
 * @return array
 */
public function __serialize(): array
{
    $properties = [];

    foreach ((array) $this as $property => $value) {
        if (self::isSerializable($value)) {
            $properties[$property] = $value;
        }
    }

    if ($this->localTranslator) {
        $properties["\0*\0dumpLocale"] = $this->locale();
    }

    return $properties;
}

/**
 * Set locale if specified on unserialize() called.
 */
public function __wakeup(): void
{
    if (isset($this->dumpLocale)) {
        $locale = $this->dumpLocale;
        $this->dumpLocale = null;
        $this->locale($locale);
    }
}

private static function isSerializable(mixed $value): bool
{
    if ($value instanceof Closure) {
        return false;
    }

    if (\is_array($value)) {
        foreach ($value as $item) {
            if (!self::isSerializable($item)) {
                return false;
            }
        }
    }

    return true;
}

