/**
 * Restore an instance from a serialized string, reconstructing the internal
 * DateInterval state and re-creating the local translator (if any) from the
 * dumped locale, as Closures (like the ones embedded in translators) cannot
 * be serialized.
 *
 * @param array $data data as returned by __serialize()
 */
public function __unserialize(array $data): void
{
    $properties = [];

    foreach ($data as $key => $value) {
        $properties[\substr($key, (int) (strrpos($key, "\0") ?: -1) + 1)] = $value;
    }

    // Initialize the internal DateInterval state so units can be set afterward
    parent::__construct('PT0S');

    foreach (['y', 'm', 'd', 'h', 'i', 's', 'f', 'invert'] as $unit) {
        if (\array_key_exists($unit, $properties)) {
            $this->$unit = $properties[$unit];
        }
    }

    foreach ([
        'timezoneSetting',
        'originalInput',
        'startDate',
        'endDate',
        'rawInterval',
        'initialValues',
        'clock',
        'step',
        'localMonthsOverflow',
        'localYearsOverflow',
        'localStrictModeEnabled',
        'localHumanDiffOptions',
        'localToStringFormat',
        'localSerializer',
        'localMacros',
        'localGenericMacros',
        'localFormatFunction',
        'dumpLocale',
    ] as $property) {
        if (\array_key_exists($property, $properties)) {
            $this->$property = $properties[$property];
        }
    }

    if (isset($properties['dumpLocale'])) {
        $this->locale($properties['dumpLocale']);
    }
}

private static function isSerializable(mixed $value): bool

