/**
 * Return the values to dump on serialize() called on, excluding messages
 * containing Closures (translation callbacks cannot be serialized).
 *
 * @return array
 */
public function __serialize(): array
{
    $messages = [];

    foreach ($this->messages as $locale => $localeMessages) {
        $localeMessages = self::filterSerializableMessages($localeMessages);

        if ($localeMessages) {
            $messages[$locale] = $localeMessages;
        }
    }

    return [
        'locale' => $this->getLocale(),
        'directories' => $this->directories,
        'messages' => $messages,
    ];
}

/**
 * Restore the instance from serialized data, re-initializing the underlying
 * Symfony translator and re-applying dumped custom messages.
 *
 * @param array $data data as returned by __serialize()
 */
public function __unserialize(array $data): void
{
    $this->__construct($data['locale'] ?? 'en');

    foreach ($data['directories'] ?? [] as $directory) {
        if (!\in_array($directory, $this->directories, true)) {
            $this->directories[] = $directory;
        }
    }

    foreach ($data['messages'] ?? [] as $locale => $localeMessages) {
        $this->loadMessagesFromFile($locale);
        $this->addResource('array', $localeMessages, $locale);
        $this->messages[$locale] = array_merge($this->messages[$locale] ?? [], $localeMessages);
    }
}

private static function filterSerializableMessages(array $messages): array
{
    $result = [];

    foreach ($messages as $key => $message) {
        if ($message instanceof Closure) {
            continue;
        }

        if (\is_array($message)) {
            $message = self::filterSerializableMessages($message);
        }

        $result[$key] = $message;
    }

    return $result;
}

